inline void ProcessIdentityDataView::GetSecurityContextDataView(
    mojo::StringDataView* output) {
  auto pointer = data_->security_context.Get();
  *output = mojo::StringDataView(pointer, message_);
}


inline void RegisteredServiceStateDataView::GetOwnerDataView(
    ProcessIdentityDataView* output) {
  auto pointer = data_->owner.Get();
  *output = ProcessIdentityDataView(pointer, message_);
}




inline void ServiceEventDataView::GetServiceNameDataView(
    mojo::StringDataView* output) {
  auto pointer = data_->service_name.Get();
  *output = mojo::StringDataView(pointer, message_);
}
inline void ServiceEventDataView::GetDispatcherDataView(
    ProcessIdentityDataView* output) {
  auto pointer = data_->dispatcher.Get();
  *output = ProcessIdentityDataView(pointer, message_);
}


inline void ErrorDataView::GetMessageDataView(
    mojo::StringDataView* output) {
  auto pointer = data_->message.Get();
  *output = mojo::StringDataView(pointer, message_);
}


inline void ErrorOrServiceStateDataView::GetStateDataView(
    ServiceStateDataView* output) const {
  CHECK(is_state());
  *output = ServiceStateDataView(data_->data.f_state.Get(), message_);
}
inline void ErrorOrServiceStateDataView::GetErrorDataView(
    ErrorDataView* output) const {
  CHECK(is_error());
  *output = ErrorDataView(data_->data.f_error.Get(), message_);
}

inline void ServiceStateDataView::GetRegisteredStateDataView(
    RegisteredServiceStateDataView* output) const {
  CHECK(is_registered_state());
  *output = RegisteredServiceStateDataView(data_->data.f_registered_state.Get(), message_);
}
inline void ServiceStateDataView::GetUnregisteredStateDataView(
    UnregisteredServiceStateDataView* output) const {
  CHECK(is_unregistered_state());
  *output = UnregisteredServiceStateDataView(data_->data.f_unregistered_state.Get(), message_);
}


